const input = $input.first().json;
const body = input.body || input;
const event = body;

const eventType = event.type;
const data = event.data?.object || {};

return [{
  json: {
    event_type: eventType,
    customer_id: data.customer,
    subscription_id: data.id || data.subscription,
    email: data.customer_email || data.receipt_email,
    amount: data.amount_paid || data.amount || 0,
    currency: data.currency || 'usd',
    status: data.status,
    plan_id: data.items?.data?.[0]?.price?.id || data.plan?.id,
    period_start: data.current_period_start,
    period_end: data.current_period_end,
    cancel_at: data.cancel_at,
    invoice_url: data.hosted_invoice_url || data.invoice_pdf
  }
}];

const event = $input.first().json;
let action = 'log';
let planType = 'standard';

// Map Stripe price IDs to plan types
const planMap = {
  'price_starter_monthly': 'starter',
  'price_standard_monthly': 'standard',
  'price_enterprise_monthly': 'enterprise'
};
planType = planMap[event.plan_id] || 'standard';

switch (event.event_type) {
  case 'customer.subscription.created':
    action = 'subscription_created';
    break;
  case 'customer.subscription.updated':
    action = event.cancel_at ? 'subscription_cancelling' : 'subscription_updated';
    break;
  case 'customer.subscription.deleted':
    action = 'subscription_cancelled';
    break;
  case 'invoice.paid':
    action = 'payment_received';
    break;
  case 'invoice.payment_failed':
    action = 'payment_failed';
    break;
  default:
    action = 'other';
}

return [{ json: { ...event, action, plan_type: planType } }];
